function EXTRA(R,ICON){
 /* hook cards (380 x 170) */
 ICON.mtCarnotCard=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${MT_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  ${MT_arrow(36,140,170,140,MT_DARK,3,10)}${MT_arrow(36,140,36,24,MT_DARK,3,10)}
  <rect x="62" y="52" width="88" height="64" fill="${BLU}" fill-opacity=".22" stroke="${BLU}" stroke-width="4"/>
  ${MT_T(46,34,'T',{fs:20,fill:MT_GREY})}${MT_T(166,162,'s',{fs:20,fill:MT_GREY})}
  ${MT_T(196,58,'Carnot',{fs:30,fw:800,fill:BLU})}${MT_T(196,96,'best η on paper',{fs:22,fill:MT_GREY})}${MT_T(196,134,'runs no engine',{fs:22,fw:800,fill:ORG})}</g>`;
 ICON.mtOttoCard=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${MT_box(0,0,380,170,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}
  ${MT_cyl(40,40,100,100,{gas:40})}<rect x="82" y="18" width="16" height="24" fill="${MT_STEEL}"/>
  <path d="M90,46 L80,60 L94,60 L84,76" fill="none" stroke="${ORG}" stroke-width="4" stroke-linejoin="round"/>
  ${MT_T(176,58,'Otto cycle',{fs:30,fw:800,fill:ORG})}${MT_T(176,96,'spark, then heat at',{fs:22,fill:MT_GREY})}${MT_T(176,128,'constant volume',{fs:22,fill:MT_GREY})}</g>`;
 /* recap pictures: each fills most of its card (about 420 x 330) */
 ICON.mtCarnotIc=(x,y)=>{const s=MT_arrow(20,290,410,290,MT_DARK,3,12)+MT_arrow(20,290,20,10,MT_DARK,3,12)+MT_T(34,30,'T',{fs:24,fill:MT_GREY})+MT_T(404,320,'s',{fs:24,a:'end',fill:MT_GREY})+
   `<rect x="80" y="60" width="280" height="160" fill="${BLU}" fill-opacity=".18"/>`+MT_L(80,60,80,220,BLU,5)+MT_L(360,60,360,220,BLU,5)+MT_L(80,60,360,60,ORG,7)+MT_L(80,220,360,220,GRN,7)+
   MT_T(220,40,`heat in at T${SB('H')}`,{fs:24,fw:800,a:'middle',fill:ORG})+MT_T(220,258,`heat out at T${SB('L')}`,{fs:24,fw:800,a:'middle',fill:GRN})+MT_T(220,150,`w${SB('net')}`,{fs:30,fw:800,a:'middle',fill:BLU});
  return `<g transform="translate(${x-210} ${y-170})">${s}</g>`};
 ICON.mtThreeIc=(x,y)=>{
  /* three computed p-v loops: Otto r 8 (p3 48.1 bar), Diesel r 15 (rc 1.84), Dual r 14 (rp 1.5, rc 1.5), each drawn in a 120 x 220 frame */
  const loop=(x0,type)=>{const r=type==='O'?8:type==='D'?15:14,p2=Math.pow(r,1.4),pm=62,W=120,H=230,vx=v=>x0+Math.log(v)/Math.log(r)*W,py=p=>290-Math.pow(p/pm,.5)*H;let s='';
   let v3,p3,ve;if(type==='O'){v3=1;p3=48.1;ve=1}else if(type==='D'){v3=1.84;p3=p2;ve=1.84}else{v3=1;p3=1.5*p2;ve=1.5}
   const comp=MT_range(0,1,30).map(t=>{const v=Math.pow(r,t);return [vx(v),py(Math.pow(r/v,1.4))]}),exp=MT_range(0,1,30).map(t=>{const v=ve*Math.pow(r/ve,t);return [vx(v),py(p3*Math.pow(ve/v,1.4))]});
   s+=MT_poly(comp,BLU,4)+MT_poly(exp,BLU,4)+MT_L(vx(r),py(p3*Math.pow(ve/r,1.4)),vx(r),py(1),GRN,6);
   if(type!=='D')s+=MT_L(vx(1),py(p2),vx(1),py(p3),ORG,7);if(type!=='O')s+=MT_L(vx(type==='D'?1:1),py(p3),vx(ve),py(p3),ORG,7);
   s+=MT_L(x0-6,292,x0+W+8,292,MT_DARK,3)+MT_T(x0+W/2,326,type==='O'?'Otto':type==='D'?'Diesel':'Dual',{fs:24,fw:800,a:'middle',fill:MT_DARK});return s};
  return `<g transform="translate(${x-210} ${y-175})">${loop(10,'O')+loop(150,'D')+loop(290,'U')}</g>`};
 ICON.mtRulesIc=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${MT_therm(70,20,190,.75,ORG,'kelvin')}
  ${MT_box(150,40,260,80,{fill:'#EBFBEE',st:GRN,sw:3,r:12})}${MT_T(280,92,`c${SB('p')}: constant p`,{fs:28,fw:800,a:'middle',fill:GRN})}
  ${MT_box(150,160,260,80,{fill:'#E7F5FF',st:BLU,sw:3,r:12})}${MT_T(280,212,`c${SB('v')}: constant v`,{fs:28,fw:800,a:'middle',fill:BLU})}</g>`;
}
